// Узел «Источники»: адреса поисков hh.ru, лент RSS и страниц каналов, по одному элементу на источник.
// src/sources.js (вклеено scripts/build-workflows.js, править в src/)
const sourcesLib = (() => {
  const module = { exports: {} };
// Список источников для узла «Источники»: поиски hh.ru, ленты RSS, каналы Телеграма.
// На выходе по одному адресу на источник: { kind, name, url }.
'use strict';

// Общие параметры поиска hh.ru: вся Россия, сначала свежие. Параметры источника важнее.
const HH_DEFAULTS = { area: '113', order_by: 'publication_time', items_on_page: '50' };

function hhUrl(params = {}) {
  const q = new URLSearchParams({ ...HH_DEFAULTS, ...params });
  if (!q.get('text')) throw new Error('у поиска hh.ru нет text');
  return 'https://hh.ru/search/vacancy/rss?' + q.toString();
}

function channelName(channel) {
  const name = String(channel || '').trim().replace(/^@/, '').replace(/^https?:\/\/t\.me\/(s\/)?/i, '');
  if (!/^[A-Za-z0-9_]{4,64}$/.test(name)) throw new Error(`неверное имя канала: ${channel}`);
  return name;
}

function buildSources(config = {}) {
  const out = [];
  for (const s of config.hh || []) out.push({ kind: 'rss', name: s.name, url: hhUrl(s.params) });
  for (const s of config.rss || []) {
    const u = new URL(s.url);
    if (u.protocol !== 'https:' && u.protocol !== 'http:') throw new Error(`лента не http(s): ${s.url}`);
    out.push({ kind: 'rss', name: s.name || u.hostname, url: u.href });
  }
  for (const s of config.telegram || []) {
    const ch = channelName(s.channel);
    out.push({ kind: 'telegram', name: s.name || '@' + ch, url: `https://t.me/s/${ch}` });
  }
  return out;
}

if (typeof module !== 'undefined') {
  module.exports = { HH_DEFAULTS, hhUrl, channelName, buildSources };
}
  return module.exports;
})();
// src/sources.json (вклеено scripts/build-workflows.js, править в src/)
const SOURCES = {"checked":"2026-10-02","note":"Поиск hh.ru отдаёт RSS по адресу /search/vacancy/rss с теми же параметрами, что у поиска на сайте; открытый поиск через api.hh.ru с весны 2026 закрыт без токена приложения. Каналы Телеграма читаются со страницы t.me/s/<канал>, предпросмотр у этих каналов открыт.","hh":[{"name":"hh.ru: Python без опыта","params":{"text":"python","experience":"noExperience"}},{"name":"hh.ru: стажёр-разработчик","params":{"text":"стажер разработчик"}},{"name":"hh.ru: нейросети без опыта","params":{"text":"LLM OR нейросети OR \"машинное обучение\"","experience":"noExperience"}}],"rss":[],"telegram":[{"name":"Вакансии и стажировки для начинающих","channel":"junior_vacancies"},{"name":"Python Job","channel":"job_python"},{"name":"Young & Junior","channel":"young_june"}]};

return sourcesLib.buildSources(SOURCES).map((s) => ({ json: s }));

// Узел «Отбор»: страницы источников -> вакансии -> отбор и отсев повторов с учётом журнала.
// Отсеянное пишется в журнал с причиной, дальше идёт не больше MAX_ITEMS вакансий.
// src/text.js (вклеено scripts/build-workflows.js, править в src/)
const textLib = (() => {
  const module = { exports: {} };
// Общие функции для текста: разбор сущностей HTML, очистка от тегов, сравнение строк.
// Файл без зависимостей: подходит для вклейки в узел Code n8n.
'use strict';

const NAMED = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', laquo: '«', raquo: '»', mdash: '-', ndash: '-', hellip: '…' };

function decodeEntities(s) {
  return String(s ?? '').replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const code = e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isFinite(code) && code > 0 && code < 0x110000 ? String.fromCodePoint(code) : m;
    }
    const v = NAMED[e.toLowerCase()];
    return v === undefined ? m : v;
  });
}

// HTML в обычный текст: <br> и концы абзацев становятся переносами строк.
function htmlToText(html) {
  const s = String(html ?? '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|h\d)>/gi, '\n')
    .replace(/<[^>]*>/g, '');
  return decodeEntities(s)
    .replace(/[ \t\u00a0]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// Нижний регистр, ё -> е, только буквы и цифры через пробел.
function normalizeText(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/ё/g, 'е')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

function tokens(s) {
  const t = normalizeText(s);
  return t ? t.split(' ') : [];
}

// Первая непустая строка без эмодзи и значков по краям, не длиннее max знаков.
function firstLine(text, max = 120) {
  const line = String(text || '')
    .split('\n')
    .map((l) => l.replace(/^[^\p{L}\p{N}]+|[\s:,;\-]+$/gu, '').trim())
    .find(Boolean);
  if (!line) return '';
  return line.length > max ? line.slice(0, max - 1).replace(/\s+\S*$/, '') + '…' : line;
}

if (typeof module !== 'undefined') {
  module.exports = { decodeEntities, htmlToText, normalizeText, tokens, firstLine };
}
  return module.exports;
})();
// src/rss.js (вклеено scripts/build-workflows.js, править в src/)
const rssLib = (() => {
  const module = { exports: {} };
// Разбор ленты RSS 2.0 или Atom без сторонних библиотек.
// Возвращает записи { title, link, text, date }. Текст без тегов.
'use strict';

// В узле Code n8n text.js вклеен раньше под именем textLib, require там закрыт.
const { htmlToText, decodeEntities } = typeof textLib !== 'undefined' ? textLib : require('./text.js');

function unwrap(s) {
  const m = String(s ?? '').match(/^\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*$/);
  return m ? m[1] : decodeEntities(s);
}

function tag(block, name) {
  const re = new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, 'i');
  const m = block.match(re);
  return m ? unwrap(m[1]).trim() : '';
}

function atomLink(block) {
  const links = [...block.matchAll(/<link\b([^>]*)\/?>/gi)].map((m) => m[1]);
  const pick = links.find((a) => /rel=["']alternate["']/i.test(a)) || links.find((a) => !/rel=/i.test(a)) || links[0];
  const href = pick && pick.match(/href=["']([^"']+)["']/i);
  return href ? decodeEntities(href[1]) : '';
}

function toIso(s) {
  const t = Date.parse(s);
  return Number.isFinite(t) ? new Date(t).toISOString() : null;
}

function parseFeed(xml) {
  const s = String(xml ?? '');
  const items = [...s.matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/gi)].map((m) => m[1]);
  if (items.length) {
    return items.map((b) => ({
      title: htmlToText(tag(b, 'title')),
      link: tag(b, 'link') || tag(b, 'guid'),
      text: htmlToText(tag(b, 'description') || tag(b, 'content:encoded')),
      date: toIso(tag(b, 'pubDate') || tag(b, 'dc:date')),
    }));
  }
  return [...s.matchAll(/<entry\b[^>]*>([\s\S]*?)<\/entry>/gi)].map((m) => {
    const b = m[1];
    return {
      title: htmlToText(tag(b, 'title')),
      link: atomLink(b),
      text: htmlToText(tag(b, 'summary') || tag(b, 'content')),
      date: toIso(tag(b, 'updated') || tag(b, 'published')),
    };
  });
}

if (typeof module !== 'undefined') {
  module.exports = { parseFeed };
}
  return module.exports;
})();
// src/telegram.js (вклеено scripts/build-workflows.js, править в src/)
const tgLib = (() => {
  const module = { exports: {} };
// Разбор веб-страницы канала Телеграма t.me/s/<канал>: последние ~20 постов.
// Страница открыта без входа, если у канала включён предпросмотр.
// Возвращает посты { channel, id, link, text, date }, пустые посты пропускаются.
'use strict';

// В узле Code n8n text.js вклеен раньше под именем textLib, require там закрыт.
const { htmlToText } = typeof textLib !== 'undefined' ? textLib : require('./text.js');

function parseChannelPage(html) {
  const parts = String(html ?? '').split(/data-post="/).slice(1);
  const posts = [];
  for (const part of parts) {
    const head = part.match(/^([A-Za-z0-9_]+)\/(\d+)"/);
    if (!head) continue;
    // Текст поста; цитата из ответа на другой пост (js-message_reply_text) не берётся.
    const body = part.match(/<div class="tgme_widget_message_text[^"]*js-message_text[^"]*"[^>]*>([\s\S]*?)<\/div>/);
    const text = body ? htmlToText(body[1]) : '';
    if (!text) continue;
    const time = part.match(/<time[^>]*datetime="([^"]+)"/);
    const t = time ? Date.parse(time[1]) : NaN;
    posts.push({
      channel: head[1],
      id: Number(head[2]),
      link: `https://t.me/${head[1]}/${head[2]}`,
      text,
      date: Number.isFinite(t) ? new Date(t).toISOString() : null,
    });
  }
  return posts;
}

if (typeof module !== 'undefined') {
  module.exports = { parseChannelPage };
}
  return module.exports;
})();
// src/filter.js (вклеено scripts/build-workflows.js, править в src/)
const filterLib = (() => {
  const module = { exports: {} };
// Отбор вакансий перед нейросетью: свежесть, ключевые слова, стоп-слова в заголовке,
// отсев повторов по ссылке и по похожему тексту (одна вакансия в разных каналах).
'use strict';

const { normalizeText, tokens } = typeof textLib !== 'undefined' ? textLib : require('./text.js');

const TRACKING = /^(utm_\w+|fbclid|gclid|yclid|ref|from|hhtmFrom\w*|query)$/i;

// Одна вакансия по разным ссылкам: без схемы, www, якоря, меток и конечной косой черты.
function normalizeUrl(url) {
  const raw = String(url || '').trim();
  if (!raw) return '';
  let u;
  try {
    u = new URL(raw);
  } catch {
    return raw.toLowerCase();
  }
  const params = [...u.searchParams.entries()]
    .filter(([k]) => !TRACKING.test(k))
    .sort(([a], [b]) => a.localeCompare(b));
  const query = params.length ? '?' + new URLSearchParams(params).toString() : '';
  const host = u.hostname.toLowerCase().replace(/^www\./, '');
  return host + u.pathname.replace(/\/+$/, '') + query;
}

// Слово ищется как начало слова в тексте («стажировк» найдёт «стажировка»),
// фраза как подряд идущие слова. Слова до трёх букв только целиком («ии», «ml»).
function keywordMatches(textTokens, keyword) {
  const kw = tokens(keyword);
  if (!kw.length) return false;
  for (let i = 0; i + kw.length <= textTokens.length; i++) {
    let ok = true;
    for (let j = 0; j < kw.length; j++) {
      const t = textTokens[i + j];
      const k = kw[j];
      if (k.length <= 3 ? t !== k : !t.startsWith(k)) {
        ok = false;
        break;
      }
    }
    if (ok) return true;
  }
  return false;
}

function findKeywords(text, keywords) {
  const tt = tokens(text);
  return (keywords || []).filter((k) => keywordMatches(tt, k));
}

// Отпечаток для сравнения: заголовок и начало текста.
function fingerprint(item) {
  return `${(item && item.title) || ''} ${String((item && item.text) || '').slice(0, 300)}`;
}

// Коэффициент Жаккара по основам слов (первые 5 букв), короткие слова не считаются.
function similarity(a, b) {
  const stems = (s) => new Set(tokens(s).filter((t) => t.length > 2).map((t) => t.slice(0, 5)));
  const A = stems(a);
  const B = stems(b);
  if (A.size < 3 || B.size < 3) return 0;
  let inter = 0;
  for (const x of A) if (B.has(x)) inter++;
  return inter / (A.size + B.size - inter);
}

// items: [{ title, link, text, date, source }]. seen: недавние записи журнала { link, title, text }.
// Возвращает принятые и отклонённые с причиной. options.now для проверки свежести.
function filterVacancies(items, config = {}, seen = [], options = {}) {
  const keywords = config.keywords || [];
  const exclude = config.excludeTitle || [];
  const threshold = config.similarityThreshold ?? 0.8;
  const maxAge = (config.maxAgeDays ?? 4) * 86400000;
  const now = Date.parse(options.now || new Date().toISOString());

  const accepted = [];
  const rejected = [];
  const seenUrls = new Set(seen.map((s) => normalizeUrl(s.link)).filter(Boolean));
  const seenPrints = seen.map(fingerprint);

  for (const item of items || []) {
    const reject = (reason, extra = {}) => rejected.push({ ...item, reason, ...extra });
    const title = String((item && item.title) || '').trim();
    if (!title || !item.link) {
      reject('нет заголовка или ссылки');
      continue;
    }
    const url = normalizeUrl(item.link);
    if (seenUrls.has(url)) {
      reject('повтор ссылки');
      continue;
    }
    seenUrls.add(url);
    const t = Date.parse(item.date);
    if (Number.isFinite(t) && now - t > maxAge) {
      reject('старое объявление');
      continue;
    }
    const bad = findKeywords(title, exclude);
    if (bad.length) {
      reject('стоп-слово в заголовке', { matched: bad });
      continue;
    }
    const matched = findKeywords(`${title} ${item.text || ''}`, keywords);
    if (keywords.length && !matched.length) {
      reject('нет ключевых слов');
      continue;
    }
    const print = fingerprint(item);
    let dup = null;
    for (const p of seenPrints) {
      const sim = similarity(print, p);
      if (sim >= threshold) {
        dup = Math.round(sim * 100) / 100;
        break;
      }
    }
    if (dup !== null) {
      reject('похожая вакансия уже была', { similarity: dup });
      continue;
    }
    seenPrints.push(print);
    accepted.push({ ...item, matched });
  }
  return { accepted, rejected };
}

if (typeof module !== 'undefined') {
  module.exports = { normalizeUrl, findKeywords, similarity, filterVacancies };
}
  return module.exports;
})();
// src/journal.js (вклеено scripts/build-workflows.js, править в src/)
const journalLib = (() => {
  const module = { exports: {} };
// Журнал в SQLite: что собрано, что отсеяно и почему, что ушло в подборку.
// Принимает любую базу с exec(sql) и prepare(sql) (node:sqlite или better-sqlite3).
'use strict';

const STATUSES = ['collected', 'rejected', 'matched'];

const SCHEMA = `
CREATE TABLE IF NOT EXISTS vacancies (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  url_key TEXT NOT NULL UNIQUE,
  link TEXT NOT NULL,
  title TEXT NOT NULL,
  snippet TEXT,
  source TEXT,
  status TEXT NOT NULL CHECK (status IN ('collected', 'rejected', 'matched')),
  reason TEXT,
  score REAL,
  collected_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS vacancies_status ON vacancies (status);
CREATE INDEX IF NOT EXISTS vacancies_collected_at ON vacancies (collected_at);
`;

function createJournal(db, options = {}) {
  if (!db || typeof db.exec !== 'function' || typeof db.prepare !== 'function') {
    throw new TypeError('нужен объект базы с exec и prepare');
  }
  const now = options.now || (() => new Date().toISOString());
  const normalizeUrl = options.normalizeUrl || ((u) => String(u || '').trim().toLowerCase());
  const keyOf = (link) => {
    const key = normalizeUrl(link);
    if (!key) throw new Error('нет ссылки');
    return key;
  };
  const get = (key) => db.prepare('SELECT * FROM vacancies WHERE url_key = ?').get(key) || null;

  function init() {
    db.exec(SCHEMA);
  }

  // Новая запись или уже известная ссылка: тогда { added: false } и прежняя запись.
  function collected(item) {
    const title = String((item && item.title) || '').trim();
    if (!title) throw new Error('нет заголовка');
    const key = keyOf(item.link);
    const old = get(key);
    if (old) return { added: false, item: old };
    const t = now();
    db.prepare(
      `INSERT INTO vacancies (url_key, link, title, snippet, source, status, collected_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 'collected', ?, ?)`
    ).run(key, String(item.link).trim(), title, String(item.text || '').slice(0, 300), item.source || null, t, t);
    return { added: true, item: get(key) };
  }

  function finish(link, status, reason, score) {
    const key = keyOf(link);
    const old = get(key);
    if (!old) throw new Error(`нет в журнале: ${link}`);
    if (old.status !== 'collected') throw new Error(`запись уже закрыта: ${old.status}`);
    db.prepare('UPDATE vacancies SET status = ?, reason = ?, score = ?, updated_at = ? WHERE url_key = ?').run(
      status,
      reason ?? null,
      score ?? null,
      now(),
      key
    );
    return get(key);
  }

  // У отказа всегда есть причина: по журналу видно, почему вакансия не пришла.
  function rejected(link, reason, score) {
    const r = String(reason || '').trim();
    if (!r) throw new Error('у отказа должна быть причина');
    return finish(link, 'rejected', r, score);
  }

  function matched(link, score, reason) {
    if (typeof score !== 'number' || !Number.isFinite(score)) throw new Error('нет оценки');
    return finish(link, 'matched', reason, score);
  }

  // Убрать ещё не закрытую запись: вакансия снова придёт в следующий запуск.
  // Нужно, когда нейросеть не ответила, чтобы вакансия не пропала.
  function forget(link) {
    const key = keyOf(link);
    const old = get(key);
    if (!old) return false;
    if (old.status !== 'collected') throw new Error(`запись уже закрыта: ${old.status}`);
    db.prepare('DELETE FROM vacancies WHERE url_key = ?').run(key);
    return true;
  }

  // Записи за days дней в виде { link, title, text } для filterVacancies.
  function seen(days = 30) {
    const since = new Date(Date.parse(now()) - days * 86400000).toISOString();
    return db
      .prepare('SELECT link, title, snippet FROM vacancies WHERE collected_at >= ? ORDER BY id')
      .all(since)
      .map((r) => ({ link: r.link, title: r.title, text: r.snippet || '' }));
  }

  function stats() {
    const counts = { collected: 0, rejected: 0, matched: 0 };
    for (const r of db.prepare('SELECT status, COUNT(*) AS n FROM vacancies GROUP BY status').all()) {
      counts[r.status] = Number(r.n);
    }
    const reasons = db
      .prepare(
        `SELECT reason, COUNT(*) AS n FROM vacancies WHERE status = 'rejected'
         GROUP BY reason ORDER BY n DESC, reason`
      )
      .all()
      .map((r) => ({ reason: r.reason, count: Number(r.n) }));
    return { ...counts, reasons };
  }

  return { init, collected, rejected, matched, forget, seen, stats, get: (link) => get(keyOf(link)) };
}

if (typeof module !== 'undefined') {
  module.exports = { SCHEMA, STATUSES, createJournal };
}
  return module.exports;
})();
// src/filter.config.json (вклеено scripts/build-workflows.js, править в src/)
const FILTER_CONFIG = {"keywords":["python","питон","стажер","стажировк","intern","junior","джун","начинающ","без опыта","llm","нейросет","ии","ai","ml","машинн обучени","бот","боты","ботов","fullstack","full stack","фулстек","backend","бэкенд","автоматизац","n8n"],"excludeTitle":["senior","lead","тимлид","head","руководител","ведущ","старш","директор","1с","1c","php","ios","android","продаж"],"similarityThreshold":0.8,"maxAgeDays":4};

const { DatabaseSync } = require('node:sqlite');
const settings = $('Настройки').first().json;
const maxItems = Number(settings.MAX_ITEMS) || 25;

// Источник берётся из узла «Источники» по связи элементов.
function sourceOf(i) {
  try {
    return $('Источники').itemMatching(i).json;
  } catch {
    return null;
  }
}

const items = [];
$input.all().forEach((it, i) => {
  const src = sourceOf(i);
  const body = it.json && typeof it.json.data === 'string' ? it.json.data : '';
  // Недоступный источник приходит элементом с ошибкой, без data.
  if (!src || !body) return;
  if (src.kind === 'telegram') {
    for (const p of tgLib.parseChannelPage(body)) {
      items.push({ title: textLib.firstLine(p.text), link: p.link, text: p.text.slice(0, 3000), date: p.date, source: '@' + p.channel });
    }
  } else {
    for (const r of rssLib.parseFeed(body)) {
      items.push({ title: r.title, link: r.link, text: r.text.slice(0, 3000), date: r.date, source: src.name });
    }
  }
});

const db = new DatabaseSync(settings.JR_DB_PATH);
try {
  const journal = journalLib.createJournal(db, { normalizeUrl: filterLib.normalizeUrl });
  journal.init();
  const { accepted, rejected } = filterLib.filterVacancies(items, FILTER_CONFIG, journal.seen(30));

  for (const r of rejected) {
    if (r.reason === 'повтор ссылки' || r.reason === 'нет заголовка или ссылки') continue;
    const c = journal.collected(r);
    if (c.added) journal.rejected(r.link, r.reason);
  }

  // Сверх MAX_ITEMS в журнал не пишется: эти вакансии придут в следующий запуск.
  const out = [];
  for (const a of accepted) {
    if (out.length >= maxItems) break;
